<?php
namespace App\Http\Controllers;
use App\Models\{Venue,DesignAsset,Owner};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Storage,DB};
class DesignAssetController extends Controller {
 private function own(Request $r,Venue $v):void {abort_unless($v->owner_account_id===$r->user()->id,403);}
 public function index(Request $r,Venue $venue){$this->own($r,$venue);return DesignAsset::where('venue_id',$venue->id)->orderByDesc('id')->get();}
 public function store(Request $r,Venue $venue){$this->own($r,$venue);$d=$r->validate(['kind'=>'required|in:logo,favicon','image'=>'required|image|mimes:png,jpg,jpeg,webp|max:3072|dimensions:max_width=4096,max_height=4096']);return DB::transaction(function()use($r,$venue,$d){Venue::whereKey($venue->id)->lockForUpdate()->firstOrFail();abort_if(DesignAsset::where('venue_id',$venue->id)->count()>=30,422,'Elimina un archivo sin usar antes de subir otro (máximo 30).');$path=$r->file('image')->store('venue-branding/'.$venue->id,'local');try{return response()->json(DesignAsset::create(['venue_id'=>$venue->id,'kind'=>$d['kind'],'path'=>$path]),201);}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}});}
 public function image(Request $r,DesignAsset $asset){$v=$asset->venue;$owner=$r->user() instanceof Owner&&$r->user()->id===$v->owner_account_id;$visible=$v->published&&(int)($v->design[$asset->kind.'_id']??0)===$asset->id;abort_unless($owner||$visible,404);abort_unless(Storage::disk('local')->exists($asset->path),404);return response()->file(Storage::disk('local')->path($asset->path),['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function destroy(Request $r,Venue $venue,DesignAsset $asset){$this->own($r,$venue);abort_unless($asset->venue_id===$venue->id,404);DB::transaction(function()use($venue,$asset){$v=Venue::whereKey($venue->id)->lockForUpdate()->firstOrFail();foreach([$v->design,$v->design_draft] as $d)abort_if((int)($d[$asset->kind.'_id']??0)===$asset->id,422,'El archivo está en el diseño publicado o en el borrador. Quítalo y guarda antes de eliminarlo.');$asset->delete();});Storage::disk('local')->delete($asset->path);return ['ok'=>true];}
}
